"""Generate web/src/api/types.ts from src/weaksquare/bridge/dto.py (ARCHITECTURE §3 decision 8).

Usage (from the repo root):
    uv run python scripts/gen_types.py           # write the file
    uv run python scripts/gen_types.py --check   # exit 1 if the committed file is out of date
"""

from __future__ import annotations

import argparse
import dataclasses
import sys
import types
import typing
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parent.parent
TARGET = ROOT / "web" / "src" / "api" / "types.ts"

HEADER = """\
// GENERATED by scripts/gen_types.py from src/weaksquare/bridge/dto.py. Do not edit by hand.
// Regenerate with: uv run python scripts/gen_types.py
"""


def ts_type(t: Any, known: set[str]) -> str:
    origin = typing.get_origin(t)
    args = typing.get_args(t)
    if t is type(None):
        return "null"
    if t is str:
        return "string"
    if t is bool:
        return "boolean"
    if t in (int, float):
        return "number"
    if t is Any:
        return "unknown"
    if origin is typing.Literal:
        return " | ".join(f'"{a}"' if isinstance(a, str) else str(a).lower() for a in args)
    if origin in (typing.Union, types.UnionType):
        return " | ".join(ts_type(a, known) for a in args)
    if origin in (list, tuple):
        inner = ts_type(args[0], known)
        return f"({inner})[]" if "|" in inner else f"{inner}[]"
    if origin is dict:
        return f"Record<string, {ts_type(args[1], known)}>"
    if isinstance(t, type) and t.__name__ in known:
        return t.__name__
    raise TypeError(f"no TypeScript mapping for {t!r}")


def generate() -> str:
    sys.path.insert(0, str(ROOT / "src"))
    from weaksquare.bridge import dto

    known = {c.__name__ for c in dto.EXPORTED}
    out = [HEADER]
    for cls in dto.EXPORTED:
        hints = typing.get_type_hints(cls)
        out.append(f"export interface {cls.__name__} {{")
        for f in dataclasses.fields(cls):
            out.append(f"  {f.name}: {ts_type(hints[f.name], known)};")
        out.append("}\n")
    for name, alias in getattr(dto, "TS_ALIASES", {}).items():
        out.append(f"export type {name} = {ts_type(alias, known)};\n")
    return "\n".join(out)


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    content = generate()
    if args.check:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != content:
            print(f"{TARGET.relative_to(ROOT)} is out of date: run uv run python scripts/gen_types.py")
            return 1
        return 0
    TARGET.parent.mkdir(parents=True, exist_ok=True)
    TARGET.write_text(content, encoding="utf-8", newline="\n")
    print(f"wrote {TARGET.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
